inline ::flatbuffers::Offset<Model> CreateModel(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    denox::dnx::Version version = denox::dnx::Version_DNX_VERSION_1_0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> required_features = 0,
    ::flatbuffers::Offset<denox::dnx::ModelInfo> info = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<denox::dnx::Tensor>>> tensors = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<denox::dnx::TensorInitializer>>> initializers = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> inputs = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> outputs = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<denox::dnx::Buffer>>> buffers = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<denox::dnx::ComputeDispatch>>> dispatches = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<denox::dnx::ShaderBinary>>> shader_binaries = 0,
    ::flatbuffers::Offset<denox::dnx::SymIR> sym_ir = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<denox::dnx::ValueName>>> value_names = 0) {
  ModelBuilder builder_(_fbb);
  builder_.add_value_names(value_names);
  builder_.add_sym_ir(sym_ir);
  builder_.add_shader_binaries(shader_binaries);
  builder_.add_dispatches(dispatches);
  builder_.add_buffers(buffers);
  builder_.add_outputs(outputs);
  builder_.add_inputs(inputs);
  builder_.add_initializers(initializers);
  builder_.add_tensors(tensors);
  builder_.add_info(info);
  builder_.add_required_features(required_features);
  builder_.add_version(version);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<Model> CreateModelDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    denox::dnx::Version version = denox::dnx::Version_DNX_VERSION_1_0,
    const std::vector<uint32_t> *required_features = nullptr,
    ::flatbuffers::Offset<denox::dnx::ModelInfo> info = 0,
    const std::vector<::flatbuffers::Offset<denox::dnx::Tensor>> *tensors = nullptr,
    std::vector<::flatbuffers::Offset<denox::dnx::TensorInitializer>> *initializers = nullptr,
    const std::vector<uint32_t> *inputs = nullptr,
    const std::vector<uint32_t> *outputs = nullptr,
    const std::vector<::flatbuffers::Offset<denox::dnx::Buffer>> *buffers = nullptr,
    const std::vector<::flatbuffers::Offset<denox::dnx::ComputeDispatch>> *dispatches = nullptr,
    const std::vector<::flatbuffers::Offset<denox::dnx::ShaderBinary>> *shader_binaries = nullptr,
    ::flatbuffers::Offset<denox::dnx::SymIR> sym_ir = 0,
    const std::vector<::flatbuffers::Offset<denox::dnx::ValueName>> *value_names = nullptr) {
  auto required_features__ = required_features ? _fbb.CreateVector<uint32_t>(*required_features) : 0;
  auto tensors__ = tensors ? _fbb.CreateVector<::flatbuffers::Offset<denox::dnx::Tensor>>(*tensors) : 0;
  auto initializers__ = initializers ? _fbb.CreateVectorOfSortedTables<denox::dnx::TensorInitializer>(initializers) : 0;
  auto inputs__ = inputs ? _fbb.CreateVector<uint32_t>(*inputs) : 0;
  auto outputs__ = outputs ? _fbb.CreateVector<uint32_t>(*outputs) : 0;
  auto buffers__ = buffers ? _fbb.CreateVector<::flatbuffers::Offset<denox::dnx::Buffer>>(*buffers) : 0;
  auto dispatches__ = dispatches ? _fbb.CreateVector<::flatbuffers::Offset<denox::dnx::ComputeDispatch>>(*dispatches) : 0;
  auto shader_binaries__ = shader_binaries ? _fbb.CreateVector<::flatbuffers::Offset<denox::dnx::ShaderBinary>>(*shader_binaries) : 0;
  auto value_names__ = value_names ? _fbb.CreateVector<::flatbuffers::Offset<denox::dnx::ValueName>>(*value_names) : 0;
  return denox::dnx::CreateModel(
      _fbb,
      version,
      required_features__,
      info,
      tensors__,
      initializers__,
      inputs__,
      outputs__,
      buffers__,
      dispatches__,
      shader_binaries__,
      sym_ir,
      value_names__);
}

template <bool B>
inline bool VerifyScalarSource(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, ScalarSource type) {
  switch (type) {
    case ScalarSource_NONE: {
      return true;
    }
    case ScalarSource_literal: {
      auto ptr = reinterpret_cast<const denox::dnx::ScalarLiteral *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ScalarSource_symbolic: {
      auto ptr = reinterpret_cast<const denox::dnx::SymRef *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyScalarSourceVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyScalarSource(
        verifier,  values->Get(i), types->GetEnum<ScalarSource>(i))) {
      return false;
    }
  }
  return true;
}

